def blit(img, name, cx, cy, size=32):
    """Blit a SimpleUI 1-bit icon (0 = ink) onto a grayscale PIL image."""
    rows = ICONS[name]
    n = len(rows)
    scale = size / n
    px = img.load()
    for r, row in enumerate(rows):
        y0 = cy + int(r * scale)
        y1 = max(y0 + 1, cy + int((r + 1) * scale))
        for c, v in enumerate(row):
            if v == 0:
                x0 = cx + int(c * scale)
                x1 = max(x0 + 1, cx + int((c + 1) * scale))
                for yy in range(y0, y1):
                    for xx in range(x0, x1):
                        if 0 <= xx < img.width and 0 <= yy < img.height:
                            px[xx, yy] = 0
